def put(j,k,arr):
    for l in L: j['b'][l].setdefault(k,[])
    have={x.split('|')[1].lower() for x in j['b']['en'][k]}
    n=0
    for g,d in arr:
        q=d['en'].split('|')[0].lower()
        assert q not in have,(k,q)
        for l in L:
            assert d[l].count('|')==4,(l,d[l])
            j['b'][l][k].append(f"{g}|{d[l]}")
        have.add(q);n+=1
    return n

if __name__=='__main__':
    import json
    j=json.load(open('pack.json'))
    assert 'sj' not in j
    n=0
    for k,a in [('sci',SCI),('sto',STO),('geo',GEO),('dig',DIG),('rel',REL),('relo',RELO),('relc',RELC),('t_dino',DINO)]: n+=put(j,k,a)
    j['tm']['olympics']=OLY_TM; n+=put(j,'t_olympics',OLY)
    j['sj']={'muz':MUZ_SJ}; n+=put(j,'muz',MUZ)
    j['v']+=1;j['name']='Pachet '+str(j['v']);j['date']=TODAY
    json.dump(j,open('pack.json','w'),ensure_ascii=False,separators=(',',':'))
    print('adăugate',n,'v',j['v'])
